components.css:
.ds-download { display: inline-flex; box-sizing: border-box; min-height: 2.9rem; align-items: center; padding: 0.55rem 1rem; border: 1px solid var(--ink, #211936); border-radius: 0.35rem; background: var(--action, #e5f35b); color: var(--ink, #211936); font: 700 1rem/1.35 var(--sans, system-ui, sans-serif); text-decoration: none; }
.ds-download:hover { background: var(--action-hover, #d8e847); }
.ds-download:focus-visible { outline: 2px solid var(--link, #423081); outline-offset: 4px; }

.ds-header-links { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem 1.6rem; font: 650 0.9rem/1.65 var(--sans, system-ui, sans-serif); }
.ds-header-links a { display: inline-flex; min-height: 2.75rem; align-items: center; color: var(--ink, #211936); text-decoration: none; }
.ds-header-links a:hover { text-decoration: underline; text-underline-offset: 0.22em; text-decoration-thickness: 2px; }
.ds-header-links a:focus-visible { outline: 2px solid var(--link, #423081); outline-offset: 4px; }
@media (max-width: 30rem) { .ds-header-links { gap: 0.8rem; } }

.ds-guide-index ul { margin: 0; padding: 0; list-style: none; }
.ds-guide-index a { display: flex; box-sizing: border-box; min-height: 2.75rem; align-items: center; padding: 0.35rem 0.55rem; border-left: 1px solid var(--line, #bcb4d4); color: var(--muted, #534969); font: 400 0.9rem/1.65 var(--sans, system-ui, sans-serif); text-decoration: none; }
.ds-guide-index a:hover { background: var(--inset, #eeebf9); color: var(--link, #423081); text-decoration: underline; text-underline-offset: 0.22em; text-decoration-thickness: 2px; }
.ds-guide-index a:focus-visible { outline: 2px solid var(--link, #423081); outline-offset: -2px; }
@media (max-width: 52rem) { .ds-guide-index ul { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); } }

.ds-workspace-topics { max-width: 17rem; border-bottom: 1px solid var(--line, #bcb4d4); background: var(--hero, #e5e0f9); color: var(--ink, #211936); font: 400 1rem/1.65 var(--sans, system-ui, sans-serif); }
.ds-workspace-topics details { border-top: 1px solid var(--line, #bcb4d4); }
.ds-workspace-topics summary { box-sizing: border-box; min-height: 2.75rem; padding-block: 0.6rem; cursor: pointer; font-weight: 700; }
.ds-workspace-topics summary::marker, .ds-workspace-topics details[open] summary { color: var(--link, #423081); }
.ds-workspace-topics p { margin: 0 0 0.6rem; color: var(--muted, #534969); font-size: 0.91rem; }
.ds-workspace-topics a { display: inline-block; margin-bottom: 0.8rem; color: var(--link, #423081); font-size: 0.86rem; font-weight: 700; text-decoration-thickness: 1px; text-underline-offset: 0.22em; }
.ds-workspace-topics a:hover { color: var(--ink, #211936); text-decoration-thickness: 2px; }
.ds-workspace-topics :is(a, summary):focus-visible { outline: 2px solid var(--link, #423081); outline-offset: 4px; }

.ds-console { display: grid; grid-template-columns: minmax(0, 1fr); border-radius: 0.45rem; background: var(--console, #25203a); color: var(--console-text, #f4f1ff); }
.ds-console pre { min-width: 0; overflow: auto; margin: 0; padding: 0.85rem 1rem; font: 0.84rem/1.6 var(--mono, ui-monospace, SFMono-Regular, Consolas, monospace); scrollbar-color: var(--line, #bcb4d4) var(--console, #25203a); }
.ds-console code { font: inherit; }
.ds-console pre:focus-visible { outline: 2px solid var(--action, #e5f35b); outline-offset: -2px; }

.ds-copy { min-width: 3.8rem; min-height: 2rem; padding-inline: 0.45rem; border: 1px solid #aaa0c9; border-radius: 0.25rem; background: var(--console, #25203a); color: var(--console-text, #f4f1ff); font: 650 0.75rem/1.3 var(--sans, system-ui, sans-serif); cursor: pointer; }
.ds-copy:hover { background: var(--inset, #eeebf9); color: var(--ink, #211936); }
.ds-copy:focus-visible { outline: 2px solid var(--action, #e5f35b); outline-offset: -2px; }

.ds-note { padding: 0.85rem 1rem; background: var(--inset, #eeebf9); color: var(--muted, #534969); font: 400 1rem/1.65 var(--sans, system-ui, sans-serif); }
.ds-note p { max-width: 70ch; margin: 0; }
.ds-note strong, .ds-note code { color: var(--ink, #211936); }
.ds-note code { padding: 0.08em 0.22em; border-radius: 0.2rem; background: var(--inset, #eeebf9); font: 0.87em var(--mono, ui-monospace, SFMono-Regular, Consolas, monospace); overflow-wrap: anywhere; }

.ds-inline { margin: 0; color: var(--muted, #534969); font: 400 1rem/1.65 var(--sans, system-ui, sans-serif); }
.ds-inline :is(code, kbd) { padding: 0.08em 0.22em; border-radius: 0.2rem; background: var(--inset, #eeebf9); color: var(--ink, #211936); font: 0.87em var(--mono, ui-monospace, SFMono-Regular, Consolas, monospace); overflow-wrap: anywhere; }
.ds-inline kbd { border: 1px solid var(--line, #bcb4d4); }
